import{_ as s,a as i}from"./chunks/linebox_runtime.CTuWgwg1.js";import{_ as r,o,c as a,a3 as t,j as e}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"SVG LineBox – Collecte et transmission de valeurs de lignes","description":"","frontmatter":{"title":"SVG LineBox – Collecte et transmission de valeurs de lignes"},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/svg-linebox.md","filePath":"fr/projects/grafik-visual-studio/svg-linebox.md","lastUpdated":1793128957000}'),l={name:"fr/projects/grafik-visual-studio/svg-linebox.md"};function u(d,n,c,p,m,g){return o(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="svg-linebox" tabindex="-1">SVG LineBox <a class="header-anchor" href="#svg-linebox" aria-label="Permalink to &quot;SVG LineBox {#svg-linebox}&quot;">​</a></h1><p>À partir de la version Studio 0.1.136, la ligne de sortie propose une option supplémentaire : <strong>Ajustement automatique du diviseur (SVG LineBox)</strong>, avec sa propre vitesse cible (0,05 à 5 cycles/s ; valeur par défaut : 1). Cela permet de conserver une animation fluide et bien réglée, même pour des sommes importantes. Cette option est indépendante du mécanisme de division automatique utilisé pour les entités numériques ; voir <a href="/fr/projects/grafik-visual-studio/svg-line">SVG-Line</a>.</p><p>La <strong>SVG LineBox</strong>, située dans la section <strong>HA Grafik – Spezial</strong>, agrège les valeurs numériques provenant des « SVG-Lines » qui y sont connectées. Elle calcule une somme algébrique (tenant compte des signes) et peut transmettre le résultat à des lignes de sortie, voire, en option, à une entité numérique auxiliaire (« helper ») de Home Assistant. Ce bloc est visible dans l&#39;éditeur, mais disparaît lors de l&#39;exécution (runtime) ; les lignes actives convergent alors visuellement vers son centre.</p><h2 id="im-editor-einrichten" tabindex="-1">Configuration dans l&#39;éditeur <a class="header-anchor" href="#im-editor-einrichten" aria-label="Permalink to &quot;Configuration dans l&#39;éditeur {#im-editor-einrichten}&quot;">​</a></h2><ol><li>Ajoutez une <strong>SVG LineBox</strong> ainsi que les <strong>SVG-Lines</strong> nécessaires.</li><li>Activez les <strong>points d&#39;ancrage</strong> sur la LineBox, en ne sélectionnant que les positions requises. Par défaut, les douze points sont désactivés. L&#39;option <strong>Tous les points</strong> permet de les activer ou désactiver simultanément ; il est également possible de sélectionner chaque position individuellement.</li><li>Dans la section <strong>Connexions</strong>, chaque point actif se voit attribuer un rôle : <strong>Entrée</strong>, <strong>Remise à zéro</strong> ou <strong>Sortie</strong>. Le rôle <strong>Remise à zéro</strong> est défini par défaut ; il n&#39;est pas pris en compte dans le calcul. Aucun rôle ne peut être attribué aux points désactivés.</li><li>Reliez les lignes d&#39;entrée aux entrées, et connectez une autre « SVG-Line » à une sortie. À partir de la version Studio 0.1.126, une ligne peut reprendre la valeur d&#39;un widget numérique connecté à son autre extrémité (par exemple, une entité de type « Number »). Alternativement, vous pouvez sélectionner une <strong>entité numérique</strong> via le paramètre <strong>Animation → Source de direction</strong> ; cette source de ligne dédiée est prioritaire.</li><li>Activez l&#39;option <strong>Transmettre la valeur calculée</strong> au niveau de la sortie, et <strong>Activer l&#39;animation</strong> sur la ligne de sortie. Ce n&#39;est qu&#39;alors que la somme en pilotera la direction et la vitesse.</li></ol><p>Les points d&#39;ancrage présentent les mêmes douze positions que sur les autres widgets : à gauche et à droite (en haut, au milieu, en bas) ; en haut et en bas (au quart, au milieu et aux trois quarts). Vous pouvez connecter plusieurs lignes à un même point. Ce sont les fonctions <strong>Entrée</strong> et <strong>Sortie</strong> qui déterminent le rôle, et non la simple orientation visuelle de la ligne.</p>',6),e("video",{controls:"",playsinline:"",preload:"metadata",style:{width:"100%","max-width":"960px"},"aria-label":"SVG LineBox im Editor bearbeiten"},[e("source",{src:s,type:"video/mp4"}),e("a",{href:"/videos/grafik-visual-studio/linebox_edit.mp4"},"Ouvrir la vidéo de l'éditeur")],-1),t('<p><a href="/videos/grafik-visual-studio/linebox_edit.mp4">Ouvrir directement la vidéo de l&#39;éditeur</a></p><h2 id="wie-die-summe-entsteht" tabindex="-1">Comment la somme est générée <a class="header-anchor" href="#wie-die-summe-entsteht" aria-label="Permalink to &quot;Comment la somme est générée {#wie-die-summe-entsteht}&quot;">​</a></h2><p>La LineBox prend en compte les lignes SVG visibles connectées à ses <strong>entrées</strong> si elles portent une valeur numérique valide. Une entité numérique explicitement associée à la ligne est prioritaire ; en son absence, la valeur est récupérée depuis le widget numérique connecté ou depuis une sortie LineBox activée. Dans le cas d&#39;un widget de type « Number », le multiplicateur est appliqué, sans arrondir la valeur affichée. L&#39;animation d&#39;une ligne d&#39;entrée définie manuellement reste indépendante du transfert de valeur. Concernant les valeurs transmises par les lignes : si la ligne se termine au niveau de la LineBox, sa valeur est ajoutée à la somme avec son signe d&#39;origine ; si elle y prend naissance, elle est comptabilisée avec le signe inversé. Les valeurs provenant automatiquement de widgets sont converties en fonction de l&#39;orientation de la ligne. Chaque ligne n&#39;est comptabilisée qu&#39;une seule fois au maximum. Les états manquants ou invalides sont ignorés ; en l&#39;absence d&#39;entrée valide, aucun calcul n&#39;est effectué. La valeur zéro est considérée comme valide. Les boucles de rétroaction internes sont interrompues.</p><p><strong>Exemple sans éléments auxiliaires supplémentaires :</strong> connectez un widget « Number » (réglé sur 125) et un autre « Number » (réglé sur 79) à des entrées via deux lignes : la LineBox affichera <strong>204</strong>. Connectez ensuite la sortie activée à un autre widget (de type « Number », « Red Number », « Gauge » ou « Bar »). Dans les paramètres de ce widget, sous <strong>Source de la valeur → Valeur depuis le point d&#39;ancrage</strong>, sélectionnez le <strong>point d&#39;ancrage d&#39;entrée</strong> et activez-le dans la section <strong>Points d&#39;ancrage</strong>. La valeur est alors directement reprise par l&#39;affichage ; si plusieurs lignes valides sont connectées à ce point, leurs valeurs sont additionnées en tenant compte de leur signe. En l&#39;absence de valeur valide, le code <code>--</code> s&#39;affiche. Les autres sources disponibles sont : <strong>Entité Home Assistant / Aperçu</strong> (comportement existant) et <strong>Valeur d&#39;aperçu</strong> (qui ignore toute entité renseignée).</p><p>Exemple : Deux lignes d&#39;entrée aboutissent à la LineBox, identifiées par <code>1000</code> et <code>-300</code>. La somme est représentée par <code>700</code>. Pour une troisième ligne, partant d&#39;une <strong>sortie</strong> et ayant l&#39;option <strong>Transmettre la valeur calculée</strong> activée, <code>700</code> indique un flux allant du début vers la fin. Si la ligne de sortie se termine au niveau de la boîte, le signe correspondant à son orientation est inversé. Ses couleurs, ses pointes de flèche et son type de trait restent inchangés. Si son animation est désactivée, elle demeure immobile même lorsqu&#39;une valeur lui est transmise ; de même, <code>0</code> ou l&#39;absence d&#39;entrée valide entraîne son arrêt. L&#39;utilisation de l&#39;option <strong>Diviseur SVG LineBox (lors de la transmission)</strong> sur la ligne de sortie permet d&#39;obtenir <code>700 ÷ 100 = 7</code> cycles/s. La plage générale pour l&#39;animation numérique se situe entre 0,05 et 20 cycles/s.</p><p>En position <strong>zéro</strong>, un point ne contribue ni à la somme ni à la sortie. Désactivez l&#39;option <strong>Transmettre la valeur calculée</strong> sur une sortie si vous souhaitez que la ligne SVG connectée soit à nouveau pilotée uniquement par ses propres paramètres d&#39;animation. Un simple croisement de lignes n&#39;établit aucune liaison.</p><h2 id="verbindungspunkt-und-runtime" tabindex="-1">Point de connexion et exécution (Runtime) <a class="header-anchor" href="#verbindungspunkt-und-runtime" aria-label="Permalink to &quot;Point de connexion et exécution (Runtime) {#verbindungspunkt-und-runtime}&quot;">​</a></h2><p>En mode exécution (Runtime), les lignes actives sont dirigées vers le centre de la zone invisible. Le groupe <strong>Point de connexion</strong> contrôle l&#39;affichage :</p><table tabindex="0"><thead><tr><th>Propriété</th><th>Effet</th></tr></thead><tbody><tr><td><strong>Afficher le cercle</strong></td><td>Affiche ou masque le cercle situé au-dessus des extrémités des lignes. Par défaut : activé. Il apparaît lorsqu&#39;au moins deux lignes connectées sont visibles.</td></tr><tr><td><strong>Diamètre (px)</strong></td><td>Diamètre souhaité du cercle (de 4 à 100 px) ; pour les lignes épaisses, il s&#39;agrandit si nécessaire afin de recouvrir leurs extrémités.</td></tr><tr><td><strong>Couleur de remplissage</strong>, <strong>Couleur de bordure</strong>, <strong>Épaisseur de bordure (px)</strong></td><td>Couleurs et épaisseur de la bordure du cercle ; l&#39;épaisseur peut être réglée entre 0 et 20 px.</td></tr><tr><td><strong>Afficher la valeur de sortie</strong></td><td><strong>Désactivé</strong> (par défaut), <strong>Au-dessus du cercle</strong> ou <strong>En dessous du cercle</strong>. Affiche la somme des entrées (avec signe) ; en l&#39;absence d&#39;entrée valide, un tiret s&#39;affiche. Cet affichage peut être utilisé même si le cercle est masqué.</td></tr></tbody></table><p>La valeur affichée est mise à jour en mode exécution, y compris lors du déplacement d&#39;un curseur (slider). Visuellement, le cercle se superpose aux lignes connectées, masquant ainsi leurs extrémités anguleuses.</p>',10),e("video",{controls:"",playsinline:"",preload:"metadata",style:{width:"100%","max-width":"960px"},"aria-label":"SVG LineBox in der Runtime"},[e("source",{src:i,type:"video/mp4"}),e("a",{href:"/videos/grafik-visual-studio/linebox_runtime.mp4"},"Ouvrir la vidéo du mode exécution")],-1),t('<p><a href="/videos/grafik-visual-studio/linebox_runtime.mp4">Ouvrir directement la vidéo du mode exécution</a></p><h2 id="optionaler-home-assistant-zahlenhelfer" tabindex="-1">« Helper » (assistant) numérique optionnel dans Home Assistant <a class="header-anchor" href="#optionaler-home-assistant-zahlenhelfer" aria-label="Permalink to &quot;« Helper » (assistant) numérique optionnel dans Home Assistant {#optionaler-home-assistant-zahlenhelfer}&quot;">​</a></h2><p>La transmission aux lignes de sortie s&#39;effectue en interne et ne nécessite aucun « helper » (assistant) supplémentaire. Si vous souhaitez également traiter la somme dans Home Assistant, activez l&#39;option <strong>Écrire en plus dans un assistant numérique</strong> (sous la rubrique <strong>Sortie de l&#39;assistant numérique</strong>) et sélectionnez un assistant de type <code>input_number.*</code> existant. Lors de l&#39;exécution, l&#39;application n&#39;effectue une écriture que lorsque la valeur change ; les variations rapides sont regroupées. La plage de valeurs autorisée pour cet assistant doit englober la somme potentielle. Si ce même assistant sert également de source de données pour une ligne d&#39;entrée de cette LineBox, l&#39;écriture est bloquée afin d&#39;éviter une boucle de rétroaction directe. Aucune écriture n&#39;a lieu en l&#39;absence d&#39;entrée valide.</p><p>La première version lit des entités numériques via les lignes d&#39;entrée. Il n&#39;existe pas encore de gestion spécifique des entités par connexion. L&#39;ancien nom de palette <strong>Linebox</strong> reste utilisable comme terme de recherche ; les projets enregistrés conservent le type technique <code>linebox</code> ainsi que les noms de widgets personnalisés existants.</p><p>Vous trouverez des paramètres supplémentaires concernant l&#39;historique, les couleurs, les flèches et les animations dans la section <a href="/fr/projects/grafik-visual-studio/svg-line">SVG-Line</a>.</p>',5)])])}const x=r(l,[["render",u]]);export{h as __pageData,x as default};
